func (p *exprParser) parseLabelList() ([]string, bool) {
    // at position after '('
    p.skipWS()
    labels := []string{}
    if p.i < len(p.s) && p.s[p.i] == ')' { p.i++; return labels, true } // empty by()? 
    seen := map[string]bool{}
    for {
