        id, ok := p.parseIdent()
        if !ok { return nil, false }
        if seen[id] { return nil, false }
        seen[id] = true
        labels = append(labels, id)
        p.skipWS()
        if p.i >= len(p.s) { return nil, false }
        switch p.s[p.i] {
        case ',': p.i++
        case ')': p.i++; return labels, true
        default: return nil, false
        }
    }
}
