// evalSelector returns matching counter/gauge series under a read lock.
func (s *metricStore) evalQuery(expr parsedExpr) ([]vectorEntry, bool) {
    s.mu.RLock()
    defer s.mu.RUnlock()
    // collect matches
    type sample struct { labels map[string]string; value float64 }
    var matched []sample
    for _, cur := range s.series {
        if cur.typ != "counter" && cur.typ != "gauge" { continue }
        if cur.name != expr.sel.metric { continue }
        ok := true
        for k, v := range expr.sel.matchers {
            got, has := cur.labels[k]
            if !has || got != v { ok = false; break }
        }
        if !ok { continue }
        if math.IsNaN(cur.value) || math.IsInf(cur.value, 0) { return nil, false }
        matched = append(matched, sample{copyLabels(cur.labels), cur.value})
    }
    if expr.agg == "" {
        out := make([]vectorEntry, 0, len(matched))
        for _, m := range matched {
            out = append(out, vectorEntry{Labels: m.labels, Value: m.value})
        }
        sort.Slice(out, func(i, j int) bool { return compareLabels(out[i].Labels, out[j].Labels) < 0 })
        return out, true
    }
    // aggregate
    type group struct {
        labels map[string]string
        sum    float64
        min    float64
        max    float64
        count  int
    }
    groups := map[string]*group{}
    order... 
    for _, m := range matched {
        proj := map[string]string{}
        for _, l := range expr.by { if v, ok := m.labels[l]; ok { proj[l] = v } }
        key := seriesKey("", proj)  // reuse collision-free key
        g := groups[key]
        if g == nil { g = &group{labels: proj, min: m.value, max: m.value}; groups[key] = g }
        g.sum += m.value
        if m.value < g.min { g.min = m.value }
        if m.value > g.max { g.max = m.value }
        g.count++
    }
    out := make([]vectorEntry, 0, len(groups))
    for _, g := range groups {
        var v float64
        switch expr.agg {
        case "sum": v = g.sum
        case "min": v = g.min
        case "max": v = g.max
        case "avg": v = g.sum / float64(g.count)
        }
        if math.IsNaN(v) || math.IsInf(v, 0) { return nil, false }
        out = append(out, vectorEntry{Labels: g.labels, Value: v})
    }
    sort.Slice(...)
    return out, true
}
