func handleQueryGet(w http.ResponseWriter, r *http.Request) {
    store := tenantStore(r)
    values, err := url.ParseQuery(r.URL.RawQuery)
    if err != nil {
        writeAPIError(w, "invalid_expression", http.StatusBadRequest)
        return
    }
    if len(values) != 1 { ... 400 }
